<?php foreach($events as $event): ?><div class="card card-border-merah"><div class="card-atas"><div><p class="tanggal-besar"><?= e(date_part($event['start_at'],'d')) ?></p><p class="bulan"><?= e(bulan_singkat($event['start_at'])) ?><?= $home?'':' '.e(date_part($event['start_at'],'Y')) ?></p></div><span class="label-tersedia"><?= event_available($event)?'Tersedia':'Habis' ?></span></div><div class="card-tengah"><h3 class="kota"><?= e($event['city']) ?></h3><p class="venue"><?= e($event['venue']??$event['title']) ?></p><?php if(!$home): ?><p class="paragraf-kecil"><?= e($event['description']??'') ?></p><?php endif; ?></div><a class="btn btn-merah lebar" href="<?= $home?'tur-event.php#konser-mendatang':'#pemesanan-event' ?>"<?= !$home?' data-pilih-konser="'.(int)$event['id'].'"':'' ?>><?= $home?'Info Acara':'Pesan Tiket' ?></a></div><?php endforeach; ?><?php if(!$events): ?><p class="pesan-kosong">Belum ada konser mendatang.</p><?php endif; ?>
